        // Trim whitespace from token
        char* trimmed_token = trim_whitespace(token);
        Tag* tag = get_tag_by_name(trimmed_token);
        int tag_id;
        if (tag == NULL) {
            tag_id = create_tag(trimmed_token);
        } else {
            tag_id = tag->id;
            free(tag->name);
            free(tag);
        }
        if (tag_id > 0) {
            link_tag_to_post(post_id, tag_id);
        }
        token = strtok(NULL, ",");
    }
    free(tags_copy);
